import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { transferCartCustomerWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await transferCartCustomerWorkflow(req.scope)
    .run({
      input: {
        id: "cart_123",
        customer_id: "cus_123"
      }
    })

  res.send(result)
}

